using System.Collections.Concurrent;
using System.Text;
using System.Text.Json;
using StreamMark.Core.Remend;
using RemendApi = StreamMark.Core.Remend.Remend;
using Xunit;

namespace StreamMark.Core.Tests.Remend;

/// <summary>
/// 数据驱动地回放从 TS 测试套件录制的全部调用（输入、选项、TS 实现的结果）。
/// 每个 fixture 文件对应一个原始 *.test.ts 文件。
/// </summary>
public sealed class RemendFixtureTests
{
    private static readonly string FixtureDir = Path.Combine(AppContext.BaseDirectory, "Fixtures", "remend");

    public static TheoryData<string> Files
    {
        get
        {
            var data = new TheoryData<string>();
            foreach (var path in Directory.GetFiles(FixtureDir, "*.json").Order(StringComparer.Ordinal))
            {
                data.Add(Path.GetFileNameWithoutExtension(path));
            }
            return data;
        }
    }

    [Fact]
    public void EveryTestFileHasFixtures()
    {
        // 29 test files in packages/remend/__tests__
        Assert.Equal(29, Files.Count);
    }

    [Theory]
    [MemberData(nameof(Files))]
    public void Fixture(string file)
    {
        using var doc = LoadFixture(file);
        var failures = new List<string>();
        var count = 0;
        foreach (var testCase in doc.RootElement.GetProperty("cases").EnumerateArray())
        {
            count++;
            var failure = Run(testCase);
            if (failure is not null)
            {
                failures.Add(failure);
            }
        }

        Assert.True(count > 0, $"{file} has no cases");
        Assert.True(failures.Count == 0,
            $"{failures.Count}/{count} cases failed in {file}:\n" + string.Join("\n", failures.Take(25)));
    }

    /// <summary>并发回放全部 remend 用例：线程静态的扫描缓存必须互不干扰。</summary>
    [Fact]
    public void ConcurrentCallsMatchFixtures()
    {
        var cases = new List<(string Input, RemendOptions? Options, string Expected)>();
        foreach (var path in Directory.GetFiles(FixtureDir, "*.json"))
        {
            using var doc = JsonDocument.Parse(File.ReadAllText(path));
            foreach (var testCase in doc.RootElement.GetProperty("cases").EnumerateArray())
            {
                if (testCase.GetProperty("fn").GetString() != "index.remend")
                {
                    continue;
                }
                var args = testCase.GetProperty("args");
                var options = args.GetArrayLength() > 1 ? ParseOptions(args[1]) : null;
                cases.Add((args[0].GetString()!, options, testCase.GetProperty("expected").GetString()!));
            }
        }

        var mismatches = new ConcurrentBag<string>();
        Parallel.For(0, cases.Count * 4, new ParallelOptions { MaxDegreeOfParallelism = 8 }, i =>
        {
            var (input, options, expected) = cases[(int)((i * 7919L) % cases.Count)];
            var actual = RemendApi.Complete(input, options);
            if (actual != expected)
            {
                mismatches.Add(Describe(input, expected, actual));
            }
        });
        Assert.Empty(mismatches);
    }

    internal static JsonDocument LoadFixture(string file) =>
        JsonDocument.Parse(File.ReadAllText(Path.Combine(FixtureDir, file + ".json")));

    internal static RemendOptions ParseOptions(JsonElement element)
    {
        var options = new RemendOptions();
        foreach (var property in element.EnumerateObject())
        {
            var value = property.Value;
            options = property.Name switch
            {
                "bold" => options with { Bold = value.GetBoolean() },
                "boldItalic" => options with { BoldItalic = value.GetBoolean() },
                "comparisonOperators" => options with { ComparisonOperators = value.GetBoolean() },
                "htmlTags" => options with { HtmlTags = value.GetBoolean() },
                "images" => options with { Images = value.GetBoolean() },
                "inlineCode" => options with { InlineCode = value.GetBoolean() },
                "inlineKatex" => options with { InlineKatex = value.GetBoolean() },
                "italic" => options with { Italic = value.GetBoolean() },
                "katex" => options with { Katex = value.GetBoolean() },
                "links" => options with { Links = value.GetBoolean() },
                "setextHeadings" => options with { SetextHeadings = value.GetBoolean() },
                "singleTilde" => options with { SingleTilde = value.GetBoolean() },
                "strikethrough" => options with { Strikethrough = value.GetBoolean() },
                "linkMode" => options with
                {
                    LinkMode = value.GetString() switch
                    {
                        "protocol" => LinkMode.Protocol,
                        "text-only" => LinkMode.TextOnly,
                        var other => throw new InvalidOperationException($"unknown linkMode {other}"),
                    },
                },
                "handlers" when value.GetArrayLength() == 0 => options with { Handlers = [] },
                _ => throw new InvalidOperationException($"unsupported option {property.Name}"),
            };
        }
        return options;
    }

    private static TrailingPattern PatternByRef(JsonElement element) =>
        element.GetProperty("$ref").GetString() switch
        {
            "patterns.boldPattern" => Patterns.Bold,
            "patterns.italicPattern" => Patterns.Italic,
            "patterns.boldItalicPattern" => Patterns.BoldItalic,
            "patterns.singleAsteriskPattern" => Patterns.SingleAsterisk,
            "patterns.singleUnderscorePattern" => Patterns.SingleUnderscore,
            "patterns.strikethroughPattern" => Patterns.Strikethrough,
            "patterns.halfCompleteUnderscorePattern" => Patterns.HalfCompleteUnderscore,
            "patterns.halfCompleteTildePattern" => Patterns.HalfCompleteTilde,
            var other => throw new InvalidOperationException($"unknown pattern {other}"),
        };

    private static object? Invoke(string fn, JsonElement args)
    {
        string Text(int i) => args[i].GetString()!;
        int Int(int i) => args[i].GetInt32();

        return fn switch
        {
            "index.remend" => RemendApi.Complete(Text(0), args.GetArrayLength() > 1 ? ParseOptions(args[1]) : null),
            "code-block-utils.isInsideCodeBlock" => RemendUtils.IsInsideCodeBlock(Text(0), Int(1)),
            "emphasis-handlers.countTripleAsterisks" => EmphasisHandlers.CountTripleAsterisks(Text(0)),
            "index.isWithinCodeBlock" or "utils.isWithinCodeBlock" => RemendUtils.IsWithinCodeBlock(Text(0), Int(1)),
            "index.isWithinMathBlock" or "utils.isWithinMathBlock" => RemendUtils.IsWithinMathBlock(Text(0), Int(1)),
            "index.isWithinLinkOrImageUrl" or "utils.isWithinLinkOrImageUrl" =>
                RemendUtils.IsWithinLinkOrImageUrl(Text(0), Int(1)),
            "utils.isWithinHtmlTag" => RemendUtils.IsWithinHtmlTag(Text(0), Int(1)),
            "index.isWordChar" or "utils.isWordChar" => RemendUtils.IsWordChar(Text(0)),
            "utils.isHorizontalRule" => RemendUtils.IsHorizontalRule(Text(0), Int(1), Text(2)[0]),
            "utils.findMatchingOpeningBracket" => RemendUtils.FindMatchingOpeningBracket(Text(0), Int(1)),
            "utils.findMatchingClosingBracket" => RemendUtils.FindMatchingClosingBracket(Text(0), Int(1)),
            "patterns.matchTrailing" => Patterns.MatchTrailing(Text(0), PatternByRef(args[1])) is { } match
                ? new[] { match.Groups[0].Value, match.Groups[1].Value, match.Groups[2].Value }
                : null,
            _ => throw new InvalidOperationException($"unknown fixture function {fn}"),
        };
    }

    private static bool Matches(JsonElement expected, object? actual) => expected.ValueKind switch
    {
        JsonValueKind.String => actual is string s && s == expected.GetString(),
        JsonValueKind.True => actual is true,
        JsonValueKind.False => actual is false,
        JsonValueKind.Number => actual is int n && n == expected.GetInt32(),
        JsonValueKind.Null => actual is null,
        JsonValueKind.Array => actual is string[] items
            && items.Length == expected.GetArrayLength()
            && items.Zip(expected.EnumerateArray()).All(pair => pair.First == pair.Second.GetString()),
        _ => false,
    };

    private static string? Run(JsonElement testCase)
    {
        var fn = testCase.GetProperty("fn").GetString()!;
        var args = testCase.GetProperty("args");
        var expected = testCase.GetProperty("expected");
        object? actual;
        try
        {
            actual = Invoke(fn, args);
        }
        catch (Exception ex)
        {
            return $"[{testCase.GetProperty("test").GetString()}] {fn}({args.GetRawText()}) threw {ex}";
        }
        if (Matches(expected, actual))
        {
            return null;
        }
        return $"[{testCase.GetProperty("test").GetString()}] {fn}({args.GetRawText()})\n" +
            $"    expected {expected.GetRawText()}\n    actual   {Show(actual)}";
    }

    private static string Show(object? value) => value switch
    {
        null => "null",
        string s => Quote(s),
        string[] items => "[" + string.Join(",", items.Select(Show)) + "]",
        bool b => b ? "true" : "false",
        _ => value.ToString() ?? "",
    };

    // JSON-style quoting that also tolerates lone surrogates
    internal static string Quote(string value)
    {
        var builder = new StringBuilder(value.Length + 2).Append('"');
        foreach (var c in value)
        {
            switch (c)
            {
                case '"': builder.Append("\\\""); break;
                case '\\': builder.Append("\\\\"); break;
                case '\n': builder.Append("\\n"); break;
                case '\r': builder.Append("\\r"); break;
                case '\t': builder.Append("\\t"); break;
                default:
                    if (c < ' ' || c > '~')
                    {
                        builder.Append("\\u").Append(((int)c).ToString("x4"));
                    }
                    else
                    {
                        builder.Append(c);
                    }
                    break;
            }
        }
        return builder.Append('"').ToString();
    }

    internal static string Describe(string input, string expected, string actual)
    {
        var builder = new StringBuilder();
        builder.Append("input    ").AppendLine(Show(input));
        builder.Append("expected ").AppendLine(Show(expected));
        builder.Append("actual   ").Append(Show(actual));
        return builder.ToString();
    }
}
